        # set stabilizes and is typically only a handful of linear scans.
        for _ in range(64):
            active_sum = 0.0
            active_count = 0
            for i in range(n):
                value = y[i]
                if value > theta:
                    active_sum += value
                    active_count += 1

            if active_count == 0:
                max_value = y[0]
                for i in range(1, n):
                    if y[i] > max_value:
                        max_value = y[i]
                theta = max_value - 1.0
                break

            new_theta = (active_sum - 1.0) / active_count

            stable = True
            for i in range(n):
                value = y[i]
                if (value > theta) != (value > new_theta):
                    stable = False
                    break
            theta = new_theta
            if stable:
                break

        out = np.empty(n, np.float64)
        for i in range(n):
            value = y[i] - theta
            out[i] = value if value > 0.0 else 0.0
        return out

    @nb.njit(cache=False, fastmath=True)
    def _project_sort(y):
        n = y.size
        if n == 0:
            return np.empty(0, np.float64)
        if n == 1:
            out = np.empty(1, np.float64)
            out[0] = 1.0
            return out

        sorted_y = np.sort(y)
        cumulative = 0.0
        theta = 0.0
        for j in range(n):
            value = sorted_y[n - 1 - j]
            cumulative += value
            candidate = (cumulative - 1.0) / (j + 1)
            if value > candidate:
                theta = candidate

        out = np.empty(n, np.float64)
        for i in range(n):
            value = y[i] - theta
            out[i] = value if value > 0.0 else 0.0
        return out
